// Inicialização - Monitoramento CredGestor VPS
const timestamp = new Date().toISOString();
const sessionId = 'session_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9);

return [{
  json: {
    sessionId: sessionId,
    timestamp: timestamp,
    application: 'CredGestor',
    vps: '167.235.76.26',
    status: 'monitoring',
    target: 'credgestor_app_only'
  }
}];

// Agregar dados coletados
const initData = $('Inicializar Monitoramento').item.json;
const healthApi = $('Health Check API').item.json;
const metrics = $('Verificar Métricas').item.json;
const frontend = $('Health Check Frontend').item.json;
const dbConnections = $('Verificar Conexões DB').item.json[0] || {};

const analysis = {
  api: {
    status: healthApi.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: healthApi.statusCode,
    response: healthApi.body || {}
  },
  metrics: {
    status: metrics.statusCode === 200 ? 'available' : 'unavailable',
    hasData: metrics.statusCode === 200
  },
  frontend: {
    status: frontend.statusCode === 200 ? 'healthy' : 'unhealthy',
    statusCode: frontend.statusCode
  },
  database: {
    totalConnections: parseInt(dbConnections.total_connections || 0),
    activeConnections: parseInt(dbConnections.active_connections || 0),
    idleConnections: parseInt(dbConnections.idle_connections || 0),
    status: 'healthy'
  }
};

// Detectar problemas
const issues = [];
if (analysis.api.status === 'unhealthy' || analysis.metrics.status === 'unavailable') {
  issues.push({ type: 'infrastructure', severity: 'critical', component: 'backend', message: 'API ou métricas com problemas' });
}
if (analysis.database.totalConnections > 50 || analysis.database.activeConnections > 30) {
  issues.push({ type: 'database', severity: 'warning', component: 'database', message: 'Muitas conexões ativas: ' + analysis.database.activeConnections });
}
if (analysis.frontend.status === 'unhealthy') {
  issues.push({ type: 'frontend', severity: 'critical', component: 'frontend', message: 'Frontend retornou status ' + analysis.frontend.statusCode });
}

return [{
  json: {
    ...initData,
    analysis: analysis,
    issues: issues,
    readyForOrchestrator: issues.length > 0
  }
}];

// Processar decisão do orquestrador e chamar agentes especializados
const orchestratorResponse = $input.item.json.output || $input.item.json.text || $input.item.json;
const originalData = $('Agregar Dados').item.json;

// Parsear resposta do orquestrador
let agentsToCall = [];
try {
  let responseText = typeof orchestratorResponse === 'string' ? orchestratorResponse : JSON.stringify(orchestratorResponse);
  // Tentar extrair JSON da resposta
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    agentsToCall = parsed.agentsToCall || [];
  }
} catch (e) {
  // Fallback baseado em problemas
  if (originalData.issues.some(i => i.type === 'infrastructure')) agentsToCall.push('containers', 'infrastructure');
  if (originalData.issues.some(i => i.type === 'database')) agentsToCall.push('database');
  if (originalData.issues.some(i => i.type === 'frontend')) agentsToCall.push('fullstack');
}

// Remover duplicatas
agentsToCall = [...new Set(agentsToCall)];

// Preparar chamadas para agentes
const agentCalls = agentsToCall.map(agentType => ({
  agentType: agentType,
  sessionId: originalData.sessionId,
  data: originalData
}));

return agentCalls.map(call => ({ json: call }));

// Agregar respostas de todos os agentes
const agentResponses = $input.all();
const originalData = $('Agregar Dados').item.json;

const consolidated = {
  sessionId: originalData.sessionId,
  timestamp: originalData.timestamp,
  application: originalData.application,
  vps: originalData.vps,
  issues: originalData.issues,
  agentAnalyses: agentResponses.map(r => {
    const response = r.json.output || r.json.text || r.json.response || r.json;
    return {
      agentType: r.json.agentType,
      response: response,
      timestamp: new Date().toISOString()
    };
  }),
  summary: {
    totalAgentsCalled: agentResponses.length,
    agentsWithIssues: agentResponses.length
  }
};

return [{
  json: consolidated
}];

// Formatar notificação
const consolidated = $('Consolidar Respostas').item.json;
const savedReport = $('Salvar Relatório').item.json[0];

const severity = consolidated.issues.some(i => i.severity === 'critical') ? 'critical' : 'medium';
const severityEmoji = severity === 'critical' ? '🔴' : severity === 'high' ? '🟠' : '🟡';

let message = severityEmoji + ' *ALERTA AI AGENTS: CredGestor VPS*\n\n';
message += '*Workflow AI Agents v1.115* coordenou ' + consolidated.summary.totalAgentsCalled + ' agente(s)\n';
message += '*VPS:* 167.235.76.26\n';
message += '*Aplicação:* CredGestor\n';
message += '*Severidade:* ' + severity.toUpperCase() + '\n\n';

message += '*📋 PROBLEMAS DETECTADOS:*\n';
for (const issue of consolidated.issues) {
  message += '• ' + issue.type + ': ' + issue.message + ' (' + issue.severity + ')\n';
}

message += '\n*🤖 ANÁLISES DOS AGENTES:*\n';
for (const agentAnalysis of consolidated.agentAnalyses) {
  message += '\n*' + agentAnalysis.agentType + ':*\n';
  const responseText = typeof agentAnalysis.response === 'string' ? agentAnalysis.response : JSON.stringify(agentAnalysis.response);
  message += responseText.substring(0, 300) + '...\n';
}

message += '\n*⚠️ AÇÕES REQUEREM APROVAÇÃO*\n';
message += 'ID: ' + (savedReport.id || 'N/A') + '\n';

return [{
  json: {
    message: message,
    reportId: savedReport.id,
    consolidated: consolidated,
    channel: '#credgestor-alerts'
  }
}];
